insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_theatre2_v1'
from (values
('117.316.c.1.A',2,'Before a tough scene, the cast stretches, shakes out tension and runs tongue twisters together. This routine is called a ___.','["Warm-up", "Strike", "Curtain call", "Dress parade"]'::jsonb,0,'Warm-ups prepare body and voice.','original'),
('117.316.c.1.A',2,'Which warm-up best prepares the facial muscles for clear speech?','["Painting backdrops", "Exaggerated articulation drills", "Heavy lifting", "Taking tickets"]'::jsonb,1,'Articulation drills loosen the mouth and tongue.','original'),
('117.316.c.1.B',3,'An actor repeatedly rehearses a gesture that shows grief so it reads clearly from the back row. She is developing what?','["Box office totals", "Lighting cues", "Consistent stage movement to express feelings", "Costume repairs"]'::jsonb,2,'Movement technique must be repeatable.','original'),
('117.316.c.1.B',3,'Why must stage movement be consistent from rehearsal to rehearsal?','["To avoid thinking", "To shorten the script", "To confuse the cast", "So partners and designers can rely on the staging"]'::jsonb,3,'Consistency supports ensemble work.','original'),
('117.316.c.1.C',3,'An actor ends each line with a clear final consonant and projects to the last row. She is demonstrating what?','["Effective voice and diction", "Set painting", "Blocking notation", "Costume design"]'::jsonb,0,'Diction and projection reach the audience.','original'),
('117.316.c.1.C',3,'Which habit helps an actor keep vocal stamina during a long run?','["Shouting offstage", "Hydrating and resting the voice between shows", "Skipping warm-ups", "Whispering strain"]'::jsonb,1,'Vocal care sustains a run.','original'),
('117.316.c.1.D',3,'A play with a rising conflict, a climax and a falling resolution follows which dramatic structure?','["A sonnet", "A haiku", "Freytag''s pyramid", "A rondo"]'::jsonb,2,'Freytag describes dramatic arc.','original'),
('117.316.c.1.D',3,'A play meant to make audiences laugh at human foolishness belongs to which genre?','["Melodrama only", "Documentary", "Tragedy", "Comedy"]'::jsonb,3,'Comedy entertains through humor.','original'),
('117.316.c.1.E',3,'A voice-over narrator who speaks directly to the audience is a convention seen in both stage and film. This is an example of a ___.','["Theatrical convention", "Lighting gel", "Camera lens", "Costume stitch"]'::jsonb,0,'Conventions are accepted practices.','original'),
('117.316.c.1.E',3,'The audience accepts that a bare platform can represent a castle. This shows what?','["A set malfunction", "A shared theatrical convention", "A mistake", "A prop error"]'::jsonb,1,'Audiences accept symbolic staging.','original'),
('117.316.c.1.F',3,'A designer notes that her costume colors must work with the lighting palette. This illustrates what about theatre?','["Costumes do not matter", "Each element is isolated", "Its elements are interdependent", "Light is optional"]'::jsonb,2,'Elements affect each other.','original'),
('117.316.c.1.F',3,'If the sound cue is late, the actor''s timing and the lighting change are affected. This relates to what?','["A budget problem", "A seating plan", "A ticket issue", "The interdependence of theatrical elements"]'::jsonb,3,'One element depends on others.','original'),
('117.316.c.1.G',2,'Which strategy best helps memorize a long speech?','["Break it into beats and rehearse each with its motivation", "Ignore it", "Read it once", "Memorize only the first line"]'::jsonb,0,'Chunking by beats helps recall.','original'),
('117.316.c.1.G',2,'Why should an actor practice lines aloud rather than silently?','["It avoids rehearsal", "Speaking engages voice and memory together", "It replaces blocking", "It saves time"]'::jsonb,1,'Speaking reinforces memory.','original'),
('117.316.c.2.A',3,'A scene partner is uncomfortable with a physical stage action. What is the best response?','["Insist on it", "Ignore her feelings", "Pause, communicate and adjust the action with the director", "Push forward"]'::jsonb,2,'Safe and respectful practice matters.','original'),
('117.316.c.2.A',3,'Why should actors set boundaries before an emotional scene?','["To avoid acting", "To lengthen rehearsal", "To cut the scene", "To allow expression while protecting well-being"]'::jsonb,3,'Boundaries support safe emotion.','original'),
('117.316.c.2.B',3,'In a devised piece, the ensemble builds ideas from each member''s suggestions. This shows creativity as it relates to what?','["Self and ensemble", "Only the stage manager", "Only the director", "Only the audience"]'::jsonb,0,'Creativity can be collective.','original'),
('117.316.c.2.B',3,'Which behavior supports creativity in an ensemble?','["Copying a video", "Welcoming and building on others'' ideas", "Rejecting every idea", "Staying silent"]'::jsonb,1,'Openness fuels creativity.','original'),
('117.316.c.2.C',3,'An actor uses a trembling pitch and halting rhythm to show nervousness. She is using what?','["Sound cue", "Props", "Voice and diction to express feelings", "Costume"]'::jsonb,2,'Vocal choices express emotion.','original'),
('117.316.c.2.C',3,'Which vocal choice would best show authority?','["A mumble", "A nervous giggle", "A whisper only", "A steady pace with a firm, clear tone"]'::jsonb,3,'Steady tone reads as confident.','original'),
('117.316.c.2.D',3,'An actor considers a character''s job, age and relationships before deciding how she greets others. She is applying what?','["Physical, intellectual, emotional and social interactions to portray a believable character", "Scenic painting", "Random guesses", "Lighting design"]'::jsonb,0,'Character choices reflect all dimensions.','original'),
('117.316.c.2.D',3,'Which choice makes a character more believable?','["Acting without a goal", "Actions grounded in the character''s wants and circumstances", "Copying another actor", "Ignoring the script"]'::jsonb,1,'Motivation grounds believability.','original'),
('117.316.c.2.E',3,'An actor communicates a character''s secret anxiety only through posture and small gestures. She is developing what?','["A playbill", "A set model", "Non-verbal physical technique", "A voice-over"]'::jsonb,2,'Non-verbal acting conveys inner life.','original'),
('117.316.c.2.E',3,'Which is a non-verbal way to show sadness on stage?','["A loud laugh", "A cheerful dance", "A fast sprint", "Lowered shoulders and slow movement"]'::jsonb,3,'Posture communicates feeling.','original'),
('117.316.c.2.F',3,'A group devises a scene from a news headline, writes dialogue and refines it after peer notes. What are they doing?','["Creating, devising and refining an original scene", "Counting seats", "Reciting a classic play", "Ordering costumes"]'::jsonb,0,'Devising builds new work from ideas.','original'),
('117.316.c.2.F',3,'Which step best refines an original monologue?','["Removing the ending", "Cutting unnecessary lines after a read-through", "Adding random words", "Ignoring feedback"]'::jsonb,1,'Editing clarifies a piece.','original'),
('117.316.c.3.A',2,'Which practice is part of safe stagecraft?','["Skipping training", "Leaving cords across walkways", "Wearing proper footwear and using tools correctly", "Running with scissors"]'::jsonb,2,'Safety habits protect the crew.','original'),
('117.316.c.3.A',2,'A technician coils cords and labels switches so others can find them. She is practicing what?','["Acting technique", "Playwriting", "Singing", "Effective stagecraft habits"]'::jsonb,3,'Organization supports production.','original'),
('117.316.c.3.B',3,'A script set in the 1960s Civil Rights era requires technical designers to research what?','["Cultural, social and political context for sets and costumes", "Ticket prices", "Seating charts", "Only lighting color"]'::jsonb,0,'Context informs design choices.','original'),
('117.316.c.3.B',3,'Why do designers read the script closely before building a set?','["To avoid collaboration", "To determine technical needs that fit the story", "To shorten rehearsal", "To skip planning"]'::jsonb,1,'Script analysis guides design.','original'),
('117.316.c.3.C',3,'A director reads a script to find themes, character relationships and duties for each design role. She is doing what?','["Painting a floor", "Selling tickets", "Analyzing the script to determine artistic roles and needs", "Ignoring the text"]'::jsonb,2,'Analysis assigns responsibilities.','original'),
('117.316.c.3.C',3,'Identifying the central theme of a play helps designers do what?','["Avoid reading", "Change the plot", "Eliminate scenes", "Make choices that support the message"]'::jsonb,3,'Theme guides design.','original'),
('117.316.c.3.D',3,'A student serves as assistant director, running rehearsals and taking notes. She is performing what?','["A role in production decisions", "A random task", "A ticket booth job", "A spectator role"]'::jsonb,0,'Roles shape production.','original'),
('117.316.c.3.D',3,'Which responsibility belongs to a sound designer?','["Directing actors", "Creating music and sound effects that support the story", "Writing dialogue", "Painting scenery"]'::jsonb,1,'Sound design supports the show.','original'),
('117.316.c.3.E',3,'A crew member stays focused during a long tech rehearsal and solves a cue problem calmly. She is showing what?','["Carelessness", "Distraction", "Responsibility, discipline and creative problem solving", "Avoidance"]'::jsonb,2,'Focus and calm solve problems.','original'),
('117.316.c.3.E',3,'A prop breaks right before an entrance. What shows creative problem solving?','["Blaming a castmate", "Hiding the problem", "Canceling the show", "Substituting a similar item and informing the stage manager"]'::jsonb,3,'Quick fixes keep the show running.','original'),
('117.316.c.4.A',3,'The rise of television changed how audiences consumed drama. This is an example of what?','["A historical and cultural influence on theatre", "A casting error", "A costume trend only", "A set malfunction"]'::jsonb,0,'Media shifts shaped theatre.','original'),
('117.316.c.4.A',3,'Analyzing how the Restoration reopened theatres after a ban involves which influence?','["Weather", "Historical and political", "Sports", "Geography only"]'::jsonb,1,'Politics influenced theatre.','original'),
('117.316.c.4.B',3,'Characters in sitcoms often echo stock characters from comedy of earlier eras. This shows how theatre, television and film do what?','["Avoid each other", "Rely on silence", "Influence our daily lives and each other", "Never overlap"]'::jsonb,2,'Forms borrow from each other.','original'),
('117.316.c.4.B',3,'A viral video inspires a school scene. This shows the role of media in what?','["Set storage", "Silence", "Isolation", "Everyday life and artistic creation"]'::jsonb,3,'Media shape creative ideas.','original'),
('117.316.c.4.C',3,'A student compares the experience of seeing a play in person with watching it streamed. She is evaluating what?','["The impact of live theatre and electronic media", "Parking", "Ticket pricing", "Seat cushions"]'::jsonb,0,'Live and recorded experiences differ.','original'),
('117.316.c.4.C',3,'Which factor is unique to live theatre?','["Editing after the fact", "Actors and audience share the same space in real time", "Multiple takes", "Special effects only"]'::jsonb,1,'Live theatre is immediate.','original'),
('117.316.c.4.D',3,'A student researches how Japanese Kabuki and Noh influenced modern theatre. This is research into what?','["Costume sizing", "Lighting grids", "World drama and its influences", "Ticket sales"]'::jsonb,2,'World theatre shapes practice.','original'),
('117.316.c.4.D',3,'Which playwright is a key figure in French comedy?','["August Wilson", "Eugene O''Neill", "Sophocles", "Molière"]'::jsonb,3,'Molière wrote French comedies.','original'),
('117.316.c.4.E',3,'A student studies how African American playwrights shaped U.S. theatre. She is researching what?','["The multicultural heritage of U.S. drama", "A single genre only", "Costume history only", "Ancient Greek theatre"]'::jsonb,0,'U.S. drama draws on many cultures.','original'),
('117.316.c.4.E',3,'Which playwright is known for the Pittsburgh Cycle of plays about African American life?','["Arthur Miller", "August Wilson", "Neil Simon", "Tennessee Williams"]'::jsonb,1,'Wilson wrote the Pittsburgh Cycle.','original'),
('117.316.c.4.F',3,'The development of the Broadway musical is an example of what?','["An ancient ritual", "A European import only", "A U.S. innovation in the performing arts", "A silent film form"]'::jsonb,2,'Musicals are an American innovation.','original'),
('117.316.c.4.F',3,'Which is a U.S. innovation in staging?','["Commedia scenario", "Greek chorus", "Noh mask", "The modern American musical''s integration of song and story"]'::jsonb,3,'Integrated musicals are American.','original'),
('117.316.c.5.A',2,'Choosing when to applaud at a formal event and when to stay silent reflects what?','["Audience etiquette suited to the performance", "Rude behavior", "No awareness", "Random action"]'::jsonb,0,'Etiquette varies with context.','original'),
('117.316.c.5.A',2,'Which behavior fits an interactive, family-style theatre performance?','["Staying fully silent no matter what", "Responding as invited by the performers", "Leaving mid-show", "Texting aloud"]'::jsonb,1,'Interactive shows invite participation.','original'),
('117.316.c.5.B',3,'A student analyzes how a play''s design supports its message and then reflects on her own growth. She is doing what?','["Copying another", "Skipping reflection", "Analyzing theatre as art and evaluating herself as a creative being", "Ignoring design"]'::jsonb,2,'Analysis and reflection build artistry.','original'),
('117.316.c.5.B',3,'Which question encourages self-evaluation as an artist?','["What time is lunch?", "How much is the ticket?", "Who sits where?", "What choices did I make and what would I change?"]'::jsonb,3,'Reflection improves craft.','original'),
('117.316.c.5.C',3,'A student gives a peer feedback that names what worked, what confused her and one suggestion. This is ___.','["Constructive criticism", "Silence", "Gossip", "Insulting remarks"]'::jsonb,0,'Balanced specific feedback helps.','original'),
('117.316.c.5.C',3,'A director gives notes after a run-through. How should actors respond?','["Argue with each note", "Listen, ask questions and apply the notes", "Ignore them", "Leave early"]'::jsonb,1,'Receptivity improves performance.','original'),
('117.316.c.5.D',3,'A critic evaluates how a revival treats theme and character through staging choices. She is evaluating what?','["Lobby design", "Ticket revenue", "The treatment of artistic elements in a production", "Parking"]'::jsonb,2,'Evaluation covers theme, character and setting.','original'),
('117.316.c.5.D',3,'Which sentence evaluates character treatment?','["It was crowded", "The seats were red", "It was long", "The lead''s slow breathing in act two revealed her inner conflict"]'::jsonb,3,'Specific observation about character.','original'),
('117.316.c.5.E',2,'A person who manages a theatre company''s finances and marketing has which kind of career?','["Arts administration", "Wildlife biology", "Mining", "Plumbing"]'::jsonb,0,'Administrators run arts organizations.','original'),
('117.316.c.5.E',2,'Teaching drama at a school is an example of what?','["A film credit", "Theatre education career", "An avocation only", "A set job"]'::jsonb,1,'Teachers educate in theatre.','original'),
('117.316.c.5.F',3,'A student compiles scene footage, reviews and a reflective journal into a digital portfolio. She is using what?','["A paper map", "A coupon", "Technology to document and present theatre experiences", "A tuning fork"]'::jsonb,2,'Portfolios present work.','original'),
('117.316.c.5.F',3,'A research project about a historical playwright helps a student do what?','["Hide findings", "Skip sources", "Avoid presenting", "Present informed knowledge about theatre history"]'::jsonb,3,'Research supports presentation.','original'),
('117.316.c.5.G',3,'Skills from theatre like public speaking and teamwork help students in which setting?','["College and careers outside theatre", "Only in shops", "Only on stage", "Nowhere else"]'::jsonb,0,'Theatre skills transfer.','original'),
('117.316.c.5.G',3,'Learning to take direction and meet deadlines in theatre is useful in what?','["No jobs", "Many professional workplaces", "Only dance", "Only acting jobs"]'::jsonb,1,'Professional habits transfer.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
